import {
    EndFeatureMembership,
    Expose,
    Feature,
    FeatureReferenceExpression,
    Import,
    MembershipExpose,
    MembershipImport,
    MembershipReference,
    NamespaceExpose,
    NamespaceImport,
    NamespaceReference,
    OperatorExpression,
